import java.util.concurrent.RecursiveTask;
import java.util.concurrent.ForkJoinPool;

public class ArraySumCalculator extends RecursiveTask<Long> {
    private final long[] array;
    private final int start;
    private final int end;
    private static final int THRESHOLD = 10_000;

    public ArraySumCalculator(long[] array, int start, int end) {
        this.array = array;
        this.start = start;
        this.end = end;
    }

    @Override
    protected Long compute() {
        int length = end - start;
        if (length <= THRESHOLD) {
            long sum = 0;
            for (int i = start; i < end; i++) {
                sum += array[i];
            }
            return sum;
        }

        int mid = start + length / 2;
        ArraySumCalculator leftTask = new ArraySumCalculator(array, start, mid);
        ArraySumCalculator rightTask = new ArraySumCalculator(array, mid, end);

        leftTask.fork(); // Asynchronously execute the left sub-task
        long rightResult = rightTask.compute(); // Compute right sub-task locally
        long leftResult = leftTask.join(); // Wait for left sub-task result

        return leftResult + rightResult;
    }

    public static void main(String[] args) {
        long[] data = new long[1_000_000];
        // Populate data...
        try (ForkJoinPool pool = new ForkJoinPool()) {
            long totalSum = pool.invoke(new ArraySumCalculator(data, 0, data.length));
            System.out.println("Total Sum: " + totalSum);
        }
    }
}
